def calc(expr: str) -> float:
    """Evaluate an arithmetic expression with Python semantics.

    Supports non-negative integer/decimal literals, binary + - * / **,
    unary + and -, parentheses and spaces. Follows Python's precedence
    and associativity exactly: ** is right-associative and binds tighter
    than a unary minus on its left (-2**2 == -4), while its right operand
    may be unary (2**-1 == 0.5). / is true division.
    """
    # ------------------------------ tokenizer ------------------------------
    DIGITS = "0123456789"
    tokens = []  # (kind, value) pairs; kinds: NUM, OP, LPAREN, RPAREN
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in DIGITS or c == ".":
            start = i
            while i < n and (expr[i] in DIGITS or expr[i] == "_"):
                i += 1
            if i < n and expr[i] == ".":
                i += 1
                while i < n and (expr[i] in DIGITS or expr[i] == "_"):
                    i += 1
            if i < n and expr[i] in "eE":  # optional exponent part
                j = i + 1
                if j < n and expr[j] in "+-":
                    j += 1
                if j < n and expr[j] in DIGITS:
                    while j < n and (expr[j] in DIGITS or expr[j] == "_"):
                        j += 1
                    i = j
            text = expr[start:i].replace("_", "")
            if not any(ch in DIGITS for ch in text):
                raise ValueError(f"invalid numeric literal {expr[start:i]!r}")
            tokens.append(("NUM", float(text)))
            continue
        if c == "*":
            if i + 1 < n and expr[i + 1] == "*":
                tokens.append(("OP", "**"))
                i += 2
            else:
                tokens.append(("OP", "*"))
                i += 1
            continue
        if c in "+-/":
            tokens.append(("OP", c))
            i += 1
            continue
        if c == "(":
            tokens.append(("LPAREN", c))
            i += 1
            continue
        if c == ")":
            tokens.append(("RPAREN", c))
            i += 1
            continue
        raise ValueError(f"unexpected character {c!r} at position {i}")

    # -------------------------------- parser --------------------------------
    # Mirrors Python's grammar:
    #   additive       := multiplicative (('+' | '-') multiplicative)*
    #   multiplicative := unary (('*' | '/') unary)*
    #   unary          := ('+' | '-') unary | power
    #   power          := atom ('**' unary)?          # right-associative
    #   atom           := NUMBER | '(' additive ')'
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def take():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def additive():
        value = multiplicative()
        while True:
            kind, op = peek()
            if kind == "OP" and op in ("+", "-"):
                take()
                right = multiplicative()
                value = value + right if op == "+" else value - right
            else:
                return value

    def multiplicative():
        value = unary()
        while True:
            kind, op = peek()
            if kind == "OP" and op in ("*", "/"):
                take()
                right = unary()
                value = value * right if op == "*" else value / right
            else:
                return value

    def unary():
        kind, op = peek()
        if kind == "OP" and op in ("+", "-"):
            take()
            operand = unary()
            return operand if op == "+" else -operand
        return power()

    def power():
        base = atom()
        if peek() == ("OP", "**"):
            take()
            # The right operand of ** may be a unary expression, and the
            # recursion here yields right associativity (2**3**2 == 2**(3**2)).
            return base ** unary()
        return base

    def atom():
        kind, value = peek()
        if kind == "NUM":
            take()
            return value
        if kind == "LPAREN":
            take()
            value = additive()
            if peek()[0] != "RPAREN":
                raise ValueError("expected ')'")
            take()
            return value
        raise ValueError(
            "unexpected token: " + ("end of input" if kind is None else repr(value))
        )

    result = additive()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos][1]!r} after end of expression")
    return result
