def num_decodings(s: str) -> int:
    MOD = 1_000_000_007
    n = len(s)
    if n == 0:
        return 0

    # dp for the empty prefix and the first character
    prev2 = 1
    c0 = s[0]
    if c0 == '*':
        prev1 = 9
    elif c0 == '0':
        prev1 = 0
    else:
        prev1 = 1

    for i in range(1, n):
        c = s[i]
        p = s[i - 1]

        # Ways decoding c as a single letter
        if c == '*':
            cur = 9 * prev1
        elif c == '0':
            cur = 0
        else:
            cur = prev1

        # Ways decoding p+c as a two-letter code (10..26)
        if p == '*':
            if c == '*':
                # 11-19 (9) + 21-26 (6)
                cur += 15 * prev2
            elif c <= '6':
                # 1c and 2c (covers c = '0'..'6')
                cur += 2 * prev2
            else:
                # only 1c (c = '7'..'9')
                cur += prev2
        elif p == '1':
            if c == '*':
                cur += 9 * prev2  # 11-19
            else:
                cur += prev2      # 10-19
        elif p == '2':
            if c == '*':
                cur += 6 * prev2  # 21-26
            elif c <= '6':
                cur += prev2      # 20-26

        cur %= MOD
        prev2, prev1 = prev1, cur

    return prev1 % MOD
