import heapq


def alien_order(words: list[str]) -> str:
    # Collect every distinct letter that appears anywhere in words.
    letters = set()
    for w in words:
        letters.update(w)

    # Build the constraint graph from adjacent word pairs.
    adj = {c: set() for c in letters}
    indegree = {c: 0 for c in letters}

    for w1, w2 in zip(words, words[1:]):
        # A word followed by its own proper prefix is inconsistent.
        if len(w1) > len(w2) and w1.startswith(w2):
            return ''
        # The first differing character pair gives one ordering constraint.
        for c1, c2 in zip(w1, w2):
            if c1 != c2:
                if c2 not in adj[c1]:
                    adj[c1].add(c2)
                    indegree[c2] += 1
                break  # only the first difference matters

    # Kahn's algorithm with a min-heap so that, among all consistent
    # orders, we always emit the smallest available letter next.
    heap = [c for c in letters if indegree[c] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        c = heapq.heappop(heap)
        result.append(c)
        for nxt in adj[c]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    # If not all letters were emitted, the constraints contain a cycle.
    return ''.join(result) if len(result) == len(letters) else ''
