def kth_smallest_distance(nums: list[int], k: int) -> int:
    n = len(nums)
    if n < 2:
        raise ValueError("nums must contain at least two elements")
    total_pairs = n * (n - 1) // 2
    if not 1 <= k <= total_pairs:
        raise ValueError("k is out of the valid range of pair counts")

    nums = sorted(nums)

    def count_pairs_at_most(d: int) -> int:
        # Count pairs (i, j) with i < j and nums[j] - nums[i] <= d
        # using a sliding window; O(n) amortized per call.
        count = 0
        left = 0
        for right in range(n):
            while nums[right] - nums[left] > d:
                left += 1
            count += right - left
        return count

    lo, hi = 0, nums[-1] - nums[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_pairs_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
