    }
    scales = {
        'hundred': 100,
        'thousand': 1_000,
        'million': 1_000_000,
        'billion': 1_000_000_000,
    }

    words = text.split()
    negative = False
    if words and words[0] == 'minus':
        negative = True
        words = words[1:]

