def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    """Evaluate a boolean expression.

    Tokens: identifiers (looked up in ``env``), the literals ``true`` and
    ``false``, the operators ``not``/``and``/``or``, and parentheses.
    Precedence (high to low): ``not``, ``and``, ``or``; ``and``/``or`` are
    left-associative. Raises KeyError for an identifier missing from ``env``
    and ValueError for malformed expressions.
    """
    keywords = {"true", "false", "not", "and", "or"}

    # ---- Tokenizer --------------------------------------------------------
    tokens = []  # list of (kind, text) pairs
    i, n = 0, len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch == "(":
            tokens.append(("LPAREN", ch))
            i += 1
        elif ch == ")":
            tokens.append(("RPAREN", ch))
            i += 1
        elif ch.isalpha() or ch == "_":
            j = i + 1
            while j < n and (expr[j].isalnum() or expr[j] == "_"):
                j += 1
            word = expr[i:j]
            i = j
            tokens.append((word.upper() if word in keywords else "IDENT", word))
        else:
            raise ValueError(f"Unexpected character {ch!r} at position {i}")

    # ---- Recursive-descent parser (evaluates while parsing) ---------------
    pos = 0

    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_or():
        value = parse_and()
        while peek() == "OR":
            advance()
            rhs = parse_and()
            value = value or rhs
        return value

    def parse_and():
        value = parse_not()
        while peek() == "AND":
            advance()
            rhs = parse_not()
            value = value and rhs
        return value

    def parse_not():
        if peek() == "NOT":
            advance()
            return not parse_not()
        return parse_atom()

    def parse_atom():
        kind = peek()
        if kind == "LPAREN":
            advance()
            value = parse_or()
            if peek() != "RPAREN":
                raise ValueError("Expected ')'")
            advance()
            return value
        if kind == "TRUE":
            advance()
            return True
        if kind == "FALSE":
            advance()
            return False
        if kind == "IDENT":
            name = advance()[1]
            return env[name]  # raises KeyError for unknown identifiers
        if kind is None:
            raise ValueError("Unexpected end of expression")
        raise ValueError(f"Unexpected token {tokens[pos][1]!r}")

    result = parse_or()
    if pos != len(tokens):
        raise ValueError(f"Unexpected token {tokens[pos][1]!r} after end of expression")
    return result
