def parse_json(text: str) -> object:
    """Parse a JSON document (RFC 8259) into Python objects.

    object -> dict, array -> list, string -> str, number -> int (when it has
    no fraction or exponent) or float, true/false/null -> True/False/None.

    Raises ValueError for any invalid input.
    """
    n = len(text)
    WS = ' \t\n\r'
    HEX_DIGITS = '0123456789abcdefABCDEF'
    SIMPLE_ESCAPES = {
        '"': '"', '\\': '\\', '/': '/',
        'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t',
    }

    def skip_ws(i):
        while i < n and text[i] in WS:
            i += 1
        return i

    def parse_value(i):
        i = skip_ws(i)
        if i >= n:
            raise ValueError("unexpected end of input")
        c = text[i]
        if c == '{':
            return parse_object(i)
        if c == '[':
            return parse_array(i)
        if c == '"':
            return parse_string(i)
        if c == 't' and text.startswith('true', i):
            return True, i + 4
        if c == 'f' and text.startswith('false', i):
            return False, i + 5
        if c == 'n' and text.startswith('null', i):
            return None, i + 4
        if c == '-' or '0' <= c <= '9':
            return parse_number(i)
        raise ValueError(f"unexpected character {c!r} at position {i}")

    def parse_object(i):
        obj = {}
        i = skip_ws(i + 1)  # step past '{'
        if i < n and text[i] == '}':
            return obj, i + 1
        while True:
            if i >= n:
                raise ValueError("unterminated object")
            if text[i] != '"':
                raise ValueError(f"expected object key string at position {i}")
            key, i = parse_string(i)
            i = skip_ws(i)
            if i >= n:
                raise ValueError("unterminated object")
            if text[i] != ':':
                raise ValueError(f"expected ':' at position {i}")
            value, i = parse_value(i + 1)
            obj[key] = value
            i = skip_ws(i)
            if i >= n:
                raise ValueError("unterminated object")
            c = text[i]
            if c == ',':
                # A '}' here would be a trailing comma; the key check at the
                # top of the loop rejects it.
                i = skip_ws(i + 1)
                continue
            if c == '}':
                return obj, i + 1
            raise ValueError(f"expected ',' or '}}' at position {i}")

    def parse_array(i):
        arr = []
        i = skip_ws(i + 1)  # step past '['
        if i < n and text[i] == ']':
            return arr, i + 1
        while True:
            value, i = parse_value(i)
            arr.append(value)
            i = skip_ws(i)
            if i >= n:
                raise ValueError("unterminated array")
            c = text[i]
            if c == ',':
                # A ']' here would be a trailing comma; parse_value rejects it.
                i += 1
                continue
            if c == ']':
                return arr, i + 1
            raise ValueError(f"expected ',' or ']' at position {i}")

    def parse_string(i):
        i += 1  # step past the opening quote
        parts = []
        while True:
            if i >= n:
                raise ValueError("unterminated string")
            c = text[i]
            if c == '"':
                return ''.join(parts), i + 1
            if c == '\\':
                if i + 1 >= n:
                    raise ValueError("unterminated string")
                e = text[i + 1]
                if e == 'u':
                    hex4 = text[i + 2:i + 6]
                    if len(hex4) != 4 or any(h not in HEX_DIGITS for h in hex4):
                        raise ValueError("invalid \\u escape (expected 4 hex digits)")
                    # Each \uXXXX is converted on its own (no surrogate pairs).
                    parts.append(chr(int(hex4, 16)))
                    i += 6
                else:
                    ch = SIMPLE_ESCAPES.get(e)
                    if ch is None:
                        raise ValueError(f"invalid escape sequence '\\{e}'")
                    parts.append(ch)
                    i += 2
            elif c < '\x20':
                raise ValueError(f"unescaped control character at position {i}")
            else:
                parts.append(c)
                i += 1

    def parse_number(i):
        start = i
        is_float = False
        if text[i] == '-':
            i += 1
        if i >= n or not ('0' <= text[i] <= '9'):
            raise ValueError(f"invalid number at position {start}")
        if text[i] == '0':
            i += 1
            if i < n and '0' <= text[i] <= '9':
                raise ValueError(f"leading zeros not allowed (position {start})")
        else:
            while i < n and '0' <= text[i] <= '9':
                i += 1
        if i < n and text[i] == '.':
            is_float = True
            i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError(f"expected digit after '.' (position {start})")
            while i < n and '0' <= text[i] <= '9':
                i += 1
        if i < n and (text[i] == 'e' or text[i] == 'E'):
            is_float = True
            i += 1
            if i < n and (text[i] == '+' or text[i] == '-'):
                i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError(f"expected exponent digits (position {start})")
            while i < n and '0' <= text[i] <= '9':
                i += 1
        if i < n and text[i] not in WS and text[i] not in ',}]':
            raise ValueError(
                f"unexpected character {text[i]!r} after number at position {start}")
        literal = text[start:i]
        if is_float:
            return float(literal), i
        return int(literal), i

    value, i = parse_value(0)
    i = skip_ws(i)
    if i != n:
        raise ValueError(f"unexpected trailing characters at position {i}")
    return value
