def num_decodings(s: str) -> int:
    MOD = 1_000_000_007
    n = len(s)
    if n == 0:
        return 0

    def single(c: str) -> int:
        # Ways to decode a single character.
        if c == '*':
            return 9          # '*' -> 1..9
        return 0 if c == '0' else 1

    def pair(a: str, b: str) -> int:
        # Ways to decode the two-character combination (a, b) as one number (10..26).
        if a == '*':
            if b == '*':
                return 15                 # 11..19 (9) + 21..26 (6)
            return 2 if b <= '6' else 1   # '0'..'6' -> 10..16 or 20..26 (2); '7'..'9' -> 17..19 (1)
        if a == '1':
            return 9 if b == '*' else 1   # 11..19 or 10..19
        if a == '2':
            if b == '*':
                return 6                  # 21..26
            return 1 if b <= '6' else 0   # 20..26 or invalid
        return 0

    # dp over prefixes with O(1) space:
    # prev2 = dp[i-1] (ways for first i-1 chars), prev1 = dp[i] (ways for first i chars).
    prev2 = 1                 # empty prefix
    prev1 = single(s[0])      # first character
    for i in range(1, n):
        cur = (prev1 * single(s[i]) + prev2 * pair(s[i - 1], s[i])) % MOD
        prev2, prev1 = prev1, cur
    return prev1 % MOD
