    if not 1 <= k <= total_pairs:
        raise ValueError("k is out of range")

    nums = sorted(nums)

    def count_pairs_at_most(d: int) -> int:
        # Count pairs (i, j) with i < j and nums[j] - nums[i] <= d
        # using a sliding window over the sorted array: O(n).
        count = 0
        left = 0
        for right in range(n):
            while nums[right] - nums[left] > d:
                left += 1
            count += right - left
        return count

    # Binary search on the answer: smallest d such that
    # count_pairs_at_most(d) >= k is the k-th smallest distance.
    lo, hi = 0, nums[-1] - nums[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if count_pairs_at_most(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
