def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    """Evaluate a boolean expression.

    Tokens: identifiers ([A-Za-z_][A-Za-z0-9_]*), the literals ``true`` and
    ``false``, the operators ``not``, ``and``, ``or``, and parentheses.
    Precedence: not > and > or; ``and``/``or`` are left-associative.
    Identifiers are looked up in ``env`` (KeyError if absent).
    """
    # ---- Tokenizer -------------------------------------------------------
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch in '()':
            tokens.append(ch)
            i += 1
        elif ch.isalpha() or ch == '_':
            start = i
            i += 1
            while i < n and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            tokens.append(expr[start:i])
        else:
            raise ValueError(f"unexpected character {ch!r} at position {i}")

    # ---- Recursive-descent parser / evaluator ----------------------------
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_or():
        # or_expr := and_expr ('or' and_expr)*   (left-associative)
        value = parse_and()
        while peek() == 'or':
            advance()
            rhs = parse_and()
            value = value or rhs
        return value

    def parse_and():
        # and_expr := not_expr ('and' not_expr)*   (left-associative)
        value = parse_not()
        while peek() == 'and':
            advance()
            rhs = parse_not()
            value = value and rhs
        return value

    def parse_not():
        # not_expr := 'not' not_expr | atom
        if peek() == 'not':
            advance()
            return not parse_not()
        return parse_atom()

    def parse_atom():
        # atom := '(' or_expr ')' | 'true' | 'false' | identifier
        token = peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        if token == '(':
            advance()
            value = parse_or()
            if peek() != ')':
                raise ValueError(f"expected ')', got {peek()!r}")
            advance()
            return value
        if token == ')':
            raise ValueError("unexpected ')'")
        if token == 'true':
            advance()
            return True
        if token == 'false':
            advance()
            return False
        if token in ('and', 'or', 'not'):
            raise ValueError(f"unexpected operator {token!r}")
        advance()
        return env[token]  # KeyError for an unknown identifier

    result = parse_or()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return result
