import re

_NUMBER_RE = re.compile(r"\d+\.\d*|\.\d+|\d+", re.ASCII)


def _tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in "0123456789.":
            m = _NUMBER_RE.match(expr, i)
            if m is None:
                raise ValueError(f"invalid number at position {i}")
            text = m.group()
            tokens.append(("number", float(text) if "." in text else int(text)))
            i = m.end()
            continue
        if expr.startswith("**", i):
            tokens.append(("power", "**"))
            i += 2
            continue
        if c in "+-*/()":
            tokens.append(("op", c))
            i += 1
            continue
        raise ValueError(f"unexpected character {c!r} at position {i}")
    return tokens


def calc(expr: str) -> float:
    """Evaluate an arithmetic expression following Python's precedence rules.

    Grammar (mirrors Python's):
        expression := term  (('+' | '-') term)*
        term       := unary (('*' | '/') unary)*
        unary      := ('+' | '-') unary | power
        power      := atom ('**' unary)?          # right-associative; right operand may be unary
        atom       := NUMBER | '(' expression ')'
    """
    tokens = _tokenize(expr)
    index = 0

    def peek():
        return tokens[index] if index < len(tokens) else (None, None)

    def advance():
        nonlocal index
        token = tokens[index]
        index += 1
        return token

    def expression():
        value = term()
        while True:
            kind, op = peek()
            if kind == "op" and op in "+-":
                advance()
                rhs = term()
                value = value + rhs if op == "+" else value - rhs
            else:
                return value

    def term():
        value = unary()
        while True:
            kind, op = peek()
            if kind == "op" and op in "*/":
                advance()
                rhs = unary()
                value = value * rhs if op == "*" else value / rhs
            else:
                return value

    def unary():
        kind, op = peek()
        if kind == "op" and op in "+-":
            advance()
            value = unary()
            return +value if op == "+" else -value
        return power()

    def power():
        value = atom()
        if peek()[0] == "power":
            advance()
            return value ** unary()
        return value

    def atom():
        kind, value = peek()
        if kind == "number":
            advance()
            return value
        if kind == "op" and value == "(":
            advance()
            result = expression()
            kind, value = peek()
            if kind != "op" or value != ")":
                raise ValueError("expected ')'")
            advance()
            return result
        if kind is None:
            raise ValueError("unexpected end of expression")
        raise ValueError(f"unexpected token {value!r}")

    result = expression()
    kind, value = peek()
    if kind is not None:
        raise ValueError(f"unexpected token {value!r}")
    return float(result)
