def parse_json(text: str) -> object:
    """Parse a JSON document (RFC 8259) into Python objects.

    Mapping: object -> dict, array -> list, string -> str,
    number -> int (no fraction/exponent) or float,
    true -> True, false -> False, null -> None.

    Raises ValueError for any invalid input.
    """
    i = 0
    n = len(text)

    WHITESPACE = ' \t\n\r'
    DIGITS = '0123456789'
    HEX_DIGITS = '0123456789abcdefABCDEF'
    ESCAPES = {
        '"': '"',
        '\\': '\\',
        '/': '/',
        'b': '\b',
        'f': '\f',
        'n': '\n',
        'r': '\r',
        't': '\t',
    }

    def fail(message):
        raise ValueError(f'{message} (at position {i})')

    def skip_whitespace():
        nonlocal i
        while i < n and text[i] in WHITESPACE:
            i += 1

    def parse_value():
        skip_whitespace()
        if i >= n:
            fail('unexpected end of input')
        c = text[i]
        if c == '{':
            return parse_object()
        if c == '[':
            return parse_array()
        if c == '"':
            return parse_string()
        if c == 't':
            return parse_literal('true', True)
        if c == 'f':
            return parse_literal('false', False)
        if c == 'n':
            return parse_literal('null', None)
        if c == '-' or c in DIGITS:
            return parse_number()
        fail(f'unexpected character {c!r}')

    def parse_literal(word, value):
        nonlocal i
        if text.startswith(word, i):
            i += len(word)
            return value
        fail(f'invalid literal, expected {word!r}')

    def parse_string():
        nonlocal i
        i += 1  # consume the opening quote
        parts = []
        while True:
            if i >= n:
                fail('unterminated string')
            c = text[i]
            if c == '"':
                i += 1
                return ''.join(parts)
            if c == '\\':
                i += 1
                if i >= n:
                    fail('unterminated string')
                e = text[i]
                if e in ESCAPES:
                    parts.append(ESCAPES[e])
                    i += 1
                elif e == 'u':
                    i += 1
                    parts.append(parse_unicode_escape())
                else:
                    fail(f'invalid escape character {e!r}')
            elif ord(c) < 0x20:
                fail('unescaped control character in string')
            else:
                parts.append(c)
                i += 1

    def parse_unicode_escape():
        nonlocal i
        if i + 4 > n:
            fail('incomplete \\u escape')
        hex_digits = text[i:i + 4]
        for ch in hex_digits:
            if ch not in HEX_DIGITS:
                fail(f'invalid hexadecimal digit {ch!r} in \\u escape')
        i += 4
        return chr(int(hex_digits, 16))

    def parse_object():
        nonlocal i
        i += 1  # consume '{'
        obj = {}
        skip_whitespace()
        if i < n and text[i] == '}':
            i += 1
            return obj
        while True:
            skip_whitespace()
            if i >= n:
                fail('unterminated object')
            if text[i] != '"':
                fail(f'expected object key, found {text[i]!r}')
            key = parse_string()
            skip_whitespace()
            if i >= n:
                fail('unterminated object')
            if text[i] != ':':
                fail(f"expected ':' after object key, found {text[i]!r}")
            i += 1
            obj[key] = parse_value()
            skip_whitespace()
            if i >= n:
                fail('unterminated object')
            c = text[i]
            if c == ',':
                i += 1
            elif c == '}':
                i += 1
                return obj
            else:
                fail(f"expected ',' or '}}' in object, found {c!r}")

    def parse_array():
        nonlocal i
        i += 1  # consume '['
        arr = []
        skip_whitespace()
        if i < n and text[i] == ']':
            i += 1
            return arr
        while True:
            arr.append(parse_value())
            skip_whitespace()
            if i >= n:
                fail('unterminated array')
            c = text[i]
            if c == ',':
                i += 1
            elif c == ']':
                i += 1
                return arr
            else:
                fail(f"expected ',' or ']' in array, found {c!r}")

    def parse_number():
        nonlocal i
        start = i
        if i < n and text[i] == '-':
            i += 1
        if i < n and text[i] == '0':
            i += 1
            if i < n and text[i] in DIGITS:
                fail('invalid number: leading zeros are not allowed')
        elif i < n and text[i] in '123456789':
            i += 1
            while i < n and text[i] in DIGITS:
                i += 1
        else:
            fail('invalid number')
        is_float = False
        if i < n and text[i] == '.':
            is_float = True
            i += 1
            if i >= n or text[i] not in DIGITS:
                fail("invalid number: expected a digit after '.'")
            while i < n and text[i] in DIGITS:
                i += 1
        if i < n and text[i] in 'eE':
            is_float = True
            i += 1
            if i < n and text[i] in '+-':
                i += 1
            if i >= n or text[i] not in DIGITS:
                fail('invalid number: expected a digit in the exponent')
            while i < n and text[i] in DIGITS:
                i += 1
        literal = text[start:i]
        if is_float:
            return float(literal)
        return int(literal)

    value = parse_value()
    skip_whitespace()
    if i != n:
        fail(f'trailing characters after JSON document, found {text[i]!r}')
    return value
