def num_decodings(s: str) -> int:
    """Count the ways to decode s ('1'-'9' and '*' meaning any digit 1-9),
    modulo 1_000_000_007. Runs in O(n) time and O(1) extra space."""
    MOD = 1_000_000_007
    if not s:
        return 0

    first = s[0]
    if first == '0':
        return 0
    # prev2 = dp[i-2] (empty prefix), prev1 = dp[i-1] (first character)
    prev2, prev1 = 1, 9 if first == '*' else 1

    for a, b in zip(s, s[1:]):
        # Ways from decoding b as a single character.
        if b == '*':
            cur = prev1 * 9
        elif b == '0':
            cur = 0
        else:
            cur = prev1

        # Ways from decoding the pair (a, b) as a two-digit number 10..26.
        if a == '*':
            if b == '*':
                cur += prev2 * 15          # 11-19 (9) + 21-26 (6)
            elif b <= '6':
                cur += prev2 * 2           # 1X and 2X both valid
            else:
                cur += prev2               # only 1X valid
        elif a == '1':
            cur += prev2 * (9 if b == '*' else 1)  # 10-19
        elif a == '2':
            if b == '*':
                cur += prev2 * 6           # 21-26
            elif b <= '6':
                cur += prev2               # 20-26
        # Any other leading digit forms no valid pair.

        prev2, prev1 = prev1, cur % MOD

    return prev1
