import heapq


def alien_order(words: list[str]) -> str:
    # Collect every distinct letter that appears in words.
    chars = set()
    for word in words:
        chars.update(word)

    # Build the constraint graph: for each adjacent pair of words, the first
    # differing characters impose an ordering edge.
    adj = {c: set() for c in chars}

    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]
        # A word followed by its own proper prefix is inconsistent.
        if len(w1) > len(w2) and w1.startswith(w2):
            return ''
        for c1, c2 in zip(w1, w2):
            if c1 != c2:
                adj[c1].add(c2)
                break  # only the first difference gives a constraint

    # Compute in-degrees from the (deduplicated) edge sets.
    in_degree = {c: 0 for c in chars}
    for u in adj:
        for v in adj[u]:
            in_degree[v] += 1

    # Kahn's algorithm with a min-heap so that, among all consistent orders,
    # we greedily pick the smallest available letter each step, yielding the
    # lexicographically smallest valid ordering (by normal a-z order).
    heap = [c for c in chars if in_degree[c] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        c = heapq.heappop(heap)
        result.append(c)
        for nxt in adj[c]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                heapq.heappush(heap, nxt)

    # If not all letters were emitted, the constraints contain a cycle.
    if len(result) != len(chars):
        return ''
    return ''.join(result)
