def words_to_number(text: str) -> int:
    units = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5,
        'six': 6, 'seven': 7, 'eight': 8, 'nine': 9, 'ten': 10,
        'eleven': 11, 'twelve': 12, 'thirteen': 13, 'fourteen': 14,
        'fifteen': 15, 'sixteen': 16, 'seventeen': 17, 'eighteen': 18,
        'nineteen': 19,
    }
    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90,
    }
    scales = {
        'hundred': 100,
        'thousand': 1_000,
        'million': 1_000_000,
        'billion': 1_000_000_000,
    }

    tokens = text.replace('-', ' ').split()
    if not tokens:
        raise ValueError("empty input")

    negative = False
    if tokens[0] == 'minus':
        negative = True
        tokens = tokens[1:]
        if not tokens:
            raise ValueError("no number after 'minus'")

    total = 0
    current = 0
    for token in tokens:
        if token == 'and':
            continue
        if token in units:
            current += units[token]
        elif token in tens:
            current += tens[token]
        elif token == 'hundred':
            if current == 0:
                raise ValueError("misplaced 'hundred'")
            current *= 100
        elif token in ('thousand', 'million', 'billion'):
            if current == 0:
                raise ValueError(f"misplaced '{token}'")
            total += current * scales[token]
            current = 0
        else:
            raise ValueError(f"unknown word: {token!r}")

    result = total + current
    return -result if negative else result
