def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    """Evaluate a boolean expression.

    Grammar (precedence: not > and > or; and/or left-associative):
        or_expr  := and_expr ('or' and_expr)*
        and_expr := not_expr ('and' not_expr)*
        not_expr := 'not' not_expr | atom
        atom     := '(' or_expr ')' | 'true' | 'false' | IDENTIFIER

    Identifiers are looked up in ``env``; an unknown identifier raises
    KeyError. Malformed expressions raise ValueError.
    """
    # --- Tokenize ---
    tokens: list[str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch == '(' or ch == ')':
            tokens.append(ch)
            i += 1
        elif ch.isalpha() or ch == '_':
            start = i
            while i < n and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            tokens.append(expr[start:i])
        else:
            raise ValueError(f"unexpected character {ch!r} at position {i}")

    # --- Parse and evaluate (recursive descent) ---
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_or():
        value = parse_and()
        while peek() == 'or':
            advance()
            rhs = parse_and()
            value = value or rhs
        return value

    def parse_and():
        value = parse_not()
        while peek() == 'and':
            advance()
            rhs = parse_not()
            value = value and rhs
        return value

    def parse_not():
        if peek() == 'not':
            advance()
            return not parse_not()
        return parse_atom()

    def parse_atom():
        token = peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        if token == '(':
            advance()
            value = parse_or()
            if peek() != ')':
                raise ValueError("expected ')'")
            advance()
            return value
        if token == 'true':
            advance()
            return True
        if token == 'false':
            advance()
            return False
        if token in ('not', 'and', 'or', ')'):
            raise ValueError(f"unexpected token {token!r}")
        advance()
        return env[token]  # raises KeyError for an unknown identifier

    result = parse_or()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos]!r}")
    return result
